package java.util.concurrent.atomic;
public class AtomicReferenceArray<E> implements java.io.Serializable {private final Object[] values;public AtomicReferenceArray(int n){values=new Object[n];}public AtomicReferenceArray(E[] a){values=new Object[a.length];System.arraycopy(a,0,values,0,a.length);}public int length(){return values.length;}public synchronized E get(int i){return (E)values[i];}public synchronized void set(int i,E v){values[i]=v;}public void lazySet(int i,E v){set(i,v);}public synchronized E getAndSet(int i,E v){E old=(E)values[i];values[i]=v;return old;}public synchronized boolean compareAndSet(int i,E e,E v){if(values[i]!=e)return false;values[i]=v;return true;}public boolean weakCompareAndSet(int i,E e,E v){return compareAndSet(i,e,v);}public String toString(){StringBuilder b=new StringBuilder("[");for(int i=0;i<length();i++){if(i>0)b.append(", ");b.append(values[i]);}return b.append(']').toString();}}
